import { activities, renewals } from "../../data"
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
export function ActivityFeed() {
  return (
    <section className="flex h-full flex-col">
      <h2 className="mb-3 text-lg font-medium">Activity Feed</h2>
      <Card className="flex-1 gap-0 rounded-2xl p-3 shadow-border">
        {activities.map(([time, title, sub]) => (
          <div
            key={title}
            className="grid grid-cols-[5rem_1fr] gap-3 border-b px-1 py-4 last:border-0"
          >
            <span className="text-xs text-muted-foreground">{time}</span>
            <div>
              <p className="text-sm">{title}</p>
              <p className="mt-1 text-xs text-muted-foreground">{sub}</p>
            </div>
          </div>
        ))}
      </Card>
    </section>
  );
}
export function UpcomingRenewals() {
  return (
    <section className="flex h-full flex-col">
      <h2 className="mb-3 text-lg font-medium">Upcoming Renewals</h2>
      <Card className="flex-1 gap-0 rounded-2xl p-3 shadow-border">
        {renewals.map(([initials, name, type, days, tone]) => (
          <div
            key={name + days}
            className="flex items-center gap-3 border-b py-4 last:border-0"
          >
            <span className="grid size-9 place-items-center rounded-xl bg-blue-100 text-xs text-primary dark:bg-blue-950">
              {initials}
            </span>
            <div>
              <p className="text-sm">{name}</p>
              <p className="text-xs text-muted-foreground">{type}</p>
            </div>
            <Badge
              variant="secondary"
              className={`ml-auto bg-${tone}-100 text-${tone}-600 dark:bg-${tone}-950 dark:text-${tone}-50`}
            >
              {days}
            </Badge>
          </div>
        ))}
      </Card>
    </section>
  );
}
export function RiskPanel() {
  const rows = [
    ["Property", 12, "rose"],
    ["Vehicle", 8, "blue"],
    ["Liability", 9, "amber"],
    ["Life & health", 3, "green"],
  ] as const;
  return (
    <section className="flex h-full flex-col">
      <h2 className="mb-3 text-lg font-medium">Portfolio Risk</h2>
      <Card className="flex-1 gap-0 rounded-2xl p-4 shadow-border">
        {rows.map(([label, bars, tone]) => (
          <div
            key={label}
            className="flex items-center border-b py-5 last:border-0"
          >
            <span className="w-28 text-sm">{label}</span>
            <div className="flex flex-1 gap-1">
              {Array.from({ length: bars }).map((_, i) => (
                <span
                  key={i}
                  className={`h-4 w-1 rounded-full bg-${tone}-500`}
                />
              ))}
            </div>
            <span className="tabular-nums">72</span>
          </div>
        ))}
      </Card>
    </section>
  );
}

import { CalendarDays, CircleDollarSign } from "lucide-react";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
export function PolicyCard({
  policy,
}: {
  policy: {
    initials: string;
    name: string;
    type: string;
    status: string;
    tone: string;
    price: string;
    detail: string;
  };
}) {
  const tones: Record<string, string> = {
    green: "bg-green-100 text-green-600 dark:bg-green-950",
    pink: "bg-pink-100 text-pink-600 dark:bg-pink-950",
    amber: "bg-amber-100 text-amber-600 dark:bg-amber-950",
    red: "bg-red-100 text-red-600 dark:bg-red-950",
  };
  return (
    <Card className="gap-5 rounded-2xl p-3 shadow-border transition-[box-shadow,scale] hover:shadow-border-hover active:scale-[0.96]">
      <div className="flex items-start justify-between">
        <span className="grid size-10 place-items-center rounded-xl bg-blue-100 text-sm text-primary dark:bg-blue-950">
          {policy.initials}
        </span>
        <Badge variant="secondary" className={tones[policy.tone]}>
          {policy.status}
        </Badge>
      </div>
      <div className="flex-1">
        <h3 className="font-medium text-lg">{policy.name}</h3>
        <p className="text-xs text-muted-foreground">{policy.type}</p>
      </div>
      <div className="flex items-center justify-between border-t border-border/50 pt-3 text-xs">
        <span className="flex items-center gap-1">
          <CircleDollarSign className="size-4" />
          {policy.price}
        </span>
        <span className="flex items-center gap-1 rounded-full px-2 py-1  border border-border shadow-xs">
          {policy.detail.startsWith("Due") ? (
            <CalendarDays className="size-4" />
          ) : null}
          {policy.detail}
        </span>
      </div>
    </Card>
  );
}

"use client";

import { Link} from "react-router-dom";

import {
  ArrowUpRight,
  BadgeHelp,
  FileText,
  FolderOpen,
  HelpCircle,
  LayoutGrid,
  Link2,
  MessageSquareMore,
  RefreshCcw,
  Settings,
  UserRound,
  UsersRound,
  X,
} from 'lucide-react';
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { ThemeToggle } from "../theme-toggle";
import LogoIcon from "./logo-icon";

const groups = [
  {
    label: "WORKSPACE",
    items: [
      [LayoutGrid, "Overview", "/", ""],
      [MessageSquareMore, "Policy Threads", "/policy-threads", "123"],
      [FileText, "Documents", "/documents", "3,154"],
      [BadgeHelp, "Claims Hub", "/claims-hub", ""],
      [RefreshCcw, "Renewals", "/renewals", ""],
    ],
  },
  {
    label: "TEAM",
    items: [
      [UsersRound, "Clients", "/clients", ""],
      [FolderOpen, "Shared Portfolio", "/shared-portfolio", ""],
    ],
  },
  {
    label: "CONFIGURE",
    items: [
      [Link2, "Integrations", "/integrations", ""],
      [Settings, "Settings", "/settings", ""],
    ],
  },
] as const;
function Logo() {
  return (
    <div className="flex items-center gap-3">
      <LogoIcon className="size-8 text-primary" />
      <span className="text-xl font-semibold">Watermelon</span>
    </div>
  );
}
export function DashboardSidebar() {
  

  return (
    <Sidebar className="border-border portfolio-dashboard border-r">
      <SidebarHeader className="h-16 flex-row items-center justify-between border-b px-4">
        <Logo />
      </SidebarHeader>
      <SidebarContent className="px-2 py-5">
        {groups.map((group) => (
          <SidebarGroup key={group.label} className="p-0 pb-5">
            <SidebarGroupLabel className="px-3 text-xs font-normal">
              {group.label}
            </SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {group.items.map(([Icon, label, href, count]) => {
                  const isActive = label === 'Overview';
                  return (
                    <SidebarMenuItem key={label}>
                      <SidebarMenuButton
                        asChild
                        isActive={isActive}
                        className={`h-11 rounded-xl px-3 text-sm data-active:bg-white dark:data-active:bg-zinc-800 ${isActive ? 'text-primary hover:text-primary shadow-border border-0' : 'text-foreground'}`}
                      >
                        <Link to={href}>
                          <Icon
                            className={`size-5 ${isActive ? 'text-primary' : 'text-foreground'}`}
                          />
                          <span
                            className={`${isActive ? 'text-primary' : 'text-foreground'}`}
                          >
                            {label}
                          </span>
                          {count ? (
                            <span className="shadow-border ml-auto rounded-sm bg-white px-2 py-0.5 text-xs dark:bg-zinc-800">
                              {count}
                            </span>
                          ) : null}
                        </Link>
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  );
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>
      <SidebarFooter className="gap-4 p-4">
        <Card className="shadow-border gap-4 rounded-2xl p-4">
          <div className="flex justify-end">
            <Button
              variant="ghost"
              size="icon"
              className="shadow-border size-8"
            >
              <X className="size-4" />
            </Button>
          </div>
          <div className="flex justify-between text-sm">
            <span>Policy queries today</span>
            <strong className="font-medium tabular-nums">714/1000</strong>
          </div>
          <div className="flex gap-1">
            {Array.from({ length: 30 }).map((_, i) => (
              <span
                key={i}
                className={`h-4 w-1 rounded-full ${i < 16 ? 'bg-primary' : 'bg-muted'}`}
              />
            ))}
          </div>
          <Button className="shadow-primary border-primary min-h-10 border">
            Upgrade plan <ArrowUpRight className="size-4" />
          </Button>
        </Card>
        <div className="space-y-1">
          <Button
            variant="ghost"
            className="text-muted-foreground h-10 w-full justify-start gap-3 px-2"
          >
            <HelpCircle />
            Help
          </Button>
          <ThemeToggle />
          <Button
            variant="ghost"
            className="text-muted-foreground h-10 w-full justify-start gap-3 px-2"
          >
            <UserRound />
            Profile
          </Button>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}

import {
  ArrowDownRight,
  ArrowRight,
  ArrowUpRight,
  File,
  RefreshCcw,
  ShieldCheck,
  WalletCards,
} from "lucide-react";
import { Card } from "@/components/ui/card";

const stats = [
  {
    icon: ShieldCheck,
    label: "Active policies",
    value: "147,392",
    delta: "23",
    period: "this month",
    trend: "up",
    bars: [8, 10, 9, 13, 12, 15, 18, 22, 28, 35],
  },
  {
    icon: WalletCards,
    label: "Premiums Collected",
    value: "$94.2K",
    delta: "8.4%",
    period: "vs last month",
    trend: "up",
    bars: [9, 14, 18, 17, 14, 16, 22, 21, 28, 35],
  },
  {
    icon: File,
    label: "Open Claims",
    value: "17",
    delta: "4",
    period: "this week",
    trend: "down",
    bars: [14, 11, 9, 12, 10, 15,28, 13, 20, 18],
  },
  {
    icon: RefreshCcw,
    label: "Retention Rate",
    value: "91%",
    delta: "Stable",
    period: "",
    trend: "stable",
    bars: [30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  },
] as const;

const trendStyles = {
  up: {
    text: "text-green-500",
    bar: "bg-green-400/30 last:bg-green-500",
    icon: ArrowUpRight,
  },
  down: {
    text: "text-red-500",
    bar: "bg-red-400/30 last:bg-red-500",
    icon: ArrowDownRight,
  },
  stable: {
    text: "text-blue-400",
    bar: "bg-blue-400/30 last:bg-blue-500",
    icon: ArrowRight,
  },
} as const;

export function StatsGrid() {
  return (
    <Card className="grid gap-0 overflow-hidden rounded-2xl p-0 shadow-border md:grid-cols-2 xl:grid-cols-4">
      {stats.map((stat, index) => {
        const styles = trendStyles[stat.trend];
        const TrendIcon = styles.icon;

        return (
          <div
            key={stat.label}
            className={`p-4 md:p-5 ${
              index ? "border-t md:border-l border-border/50 " : "md:border-0"
            }`}
          >
            <div className="flex items-center gap-2 text-sm">
              <stat.icon className="size-4" />
              {stat.label}
            </div>

            <div className="mt-8 flex items-end justify-between">
              <div>
                <div className="text-3xl font-light tracking-tight tabular-nums">
                  {stat.value}
                </div>

                <div
                  className={`mt-2 flex items-center gap-1 text-xs ${styles.text}`}
                >
                  <TrendIcon className="size-4" />

                  <span>{stat.delta}</span>

                  {stat.period && (
                    <span className="text-muted-foreground">{stat.period}</span>
                  )}
                </div>
              </div>

              <div className="flex items-end gap-1">
                {stat.bars.map((height, i) => (
                  <span
                    key={i}
                    className={`w-1.5 rounded-full ${styles.bar}`}
                    style={{ height }}
                  />
                ))}
              </div>
            </div>
          </div>
        );
      })}
    </Card>
  );
}

"use client";
import { ThemeProvider as NextThemesProvider } from "next-themes";
export function ThemeProvider(props: React.ComponentProps<typeof NextThemesProvider>) { return <NextThemesProvider {...props} />; }

"use client";
import { Moon, Sun } from "lucide-react";
import { useTheme } from "next-themes";
import { Button } from "@/components/ui/button";
export function ThemeToggle() { const { resolvedTheme, setTheme } = useTheme(); const dark = resolvedTheme === "dark"; return <Button variant="ghost" className="h-10 w-full justify-start gap-3 px-2 text-muted-foreground" onClick={() => setTheme(dark ? "light" : "dark")}><span className="relative size-5"><Sun className={`absolute size-5 transition-[opacity,filter,scale] duration-300 ${dark ? "scale-25 opacity-0 blur-sm" : "scale-100 opacity-100"}`} /><Moon className={`absolute size-5 transition-[opacity,filter,scale] duration-300 ${dark ? "scale-100 opacity-100" : "scale-25 opacity-0 blur-sm"}`} /></span>Dark Mode</Button>; }

"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"

function Avatar({
  className,
  size = "default",
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & {
  size?: "default" | "sm" | "lg"
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      className={cn(
        "group/avatar relative flex size-8 shrink-0 rounded-full select-none after:absolute after:inset-0 after:rounded-full after:border after:border-border after:mix-blend-darken data-[size=lg]:size-10 data-[size=sm]:size-6 dark:after:mix-blend-lighten",
        className
      )}
      {...props}
    />
  )
}

function AvatarImage({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Image>) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn(
        "aspect-square size-full rounded-full object-cover",
        className
      )}
      {...props}
    />
  )
}

function AvatarFallback({
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Fallback>) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        "flex size-full items-center justify-center rounded-full bg-muted text-sm text-muted-foreground group-data-[size=sm]/avatar:text-xs",
        className
      )}
      {...props}
    />
  )
}

function AvatarBadge({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="avatar-badge"
      className={cn(
        "absolute right-0 bottom-0 z-10 inline-flex items-center justify-center rounded-full bg-primary text-primary-foreground bg-blend-color ring-2 ring-background select-none",
        "group-data-[size=sm]/avatar:size-2 group-data-[size=sm]/avatar:[&>svg]:hidden",
        "group-data-[size=default]/avatar:size-2.5 group-data-[size=default]/avatar:[&>svg]:size-2",
        "group-data-[size=lg]/avatar:size-3 group-data-[size=lg]/avatar:[&>svg]:size-2",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group"
      className={cn(
        "group/avatar-group flex -space-x-2 *:data-[slot=avatar]:ring-2 *:data-[slot=avatar]:ring-background",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroupCount({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group-count"
      className={cn(
        "relative flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm text-muted-foreground ring-2 ring-background group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3",
        className
      )}
      {...props}
    />
  )
}

export {
  Avatar,
  AvatarImage,
  AvatarFallback,
  AvatarGroup,
  AvatarGroupCount,
  AvatarBadge,
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "group/badge inline-flex h-5 w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-4xl border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-3!",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground [a]:hover:bg-primary/80",
        secondary:
          "bg-secondary text-secondary-foreground [a]:hover:bg-secondary/80",
        destructive:
          "bg-destructive/10 text-destructive focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 [a]:hover:bg-destructive/20",
        outline:
          "border-border text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground",
        ghost:
          "hover:bg-muted hover:text-muted-foreground dark:hover:bg-muted/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

function Badge({
  className,
  variant = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "span"

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      className={cn(badgeVariants({ variant }), className)}
      {...props}
    />
  )
}

export { Badge, badgeVariants }

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-lg border cursor-pointer border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import * as React from "react"

import { cn } from "@/lib/utils"

function Card({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"div"> & { size?: "default" | "sm" }) {
  return (
    <div
      data-slot="card"
      data-size={size}
      className={cn(
        "group/card flex flex-col gap-(--card-spacing) overflow-hidden rounded-xl bg-card py-(--card-spacing) text-sm text-card-foreground ring-1 ring-foreground/10 [--card-spacing:--spacing(4)] has-data-[slot=card-footer]:pb-0 has-[>img:first-child]:pt-0 data-[size=sm]:[--card-spacing:--spacing(3)] data-[size=sm]:has-data-[slot=card-footer]:pb-0 *:[img:first-child]:rounded-t-xl *:[img:last-child]:rounded-b-xl",
        className
      )}
      {...props}
    />
  )
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "group/card-header @container/card-header grid auto-rows-min items-start gap-1 rounded-t-xl px-(--card-spacing) has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-(--card-spacing)",
        className
      )}
      {...props}
    />
